import heapq

def match(orders):
    trades = []
    order_info = {}  # id -> dict(side, price, qty, seq, active)
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def match_against(book_heap, is_buy_incoming, incoming_price, remaining_qty, incoming_id):
        while remaining_qty > 0 and book_heap:
            top = book_heap[0]
            resting_id = top[2]
            info = order_info.get(resting_id)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(book_heap)
                continue
            resting_price = info['price']
            if incoming_price is not None:
                if is_buy_incoming and resting_price > incoming_price:
                    break
                if (not is_buy_incoming) and resting_price < incoming_price:
                    break
            # perform match
            heapq.heappop(book_heap)
            trade_qty = min(remaining_qty, info['qty'])
            if is_buy_incoming:
                trades.append([incoming_id, resting_id, resting_price, trade_qty])
            else:
                trades.append([resting_id, incoming_id, resting_price, trade_qty])
            info['qty'] -= trade_qty
            remaining_qty -= trade_qty
            if info['qty'] > 0:
                heapq.heappush(book_heap, top)
            else:
                info['active'] = False
        return remaining_qty

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = order_info.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            seq = seq_counter
            seq_counter += 1

            if side == 'buy':
                remaining = match_against(sell_heap, True, price, qty, oid)
                if remaining > 0:
                    order_info[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
                    heapq.heappush(buy_heap, (-price, seq, oid))
                else:
                    # fully filled, still register as inactive record (not required but safe)
                    order_info[oid] = {'side': 'buy', 'price': price, 'qty': 0, 'seq': seq, 'active': False}
            else:
                remaining = match_against(buy_heap, False, price, qty, oid)
                if remaining > 0:
                    order_info[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
                    heapq.heappush(sell_heap, (price, seq, oid))
                else:
                    order_info[oid] = {'side': 'sell', 'price': price, 'qty': 0, 'seq': seq, 'active': False}

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            seq = seq_counter
            seq_counter += 1
            if side == 'buy':
                remaining = match_against(sell_heap, True, price, qty, oid)
            else:
                remaining = match_against(buy_heap, False, price, qty, oid)
            order_info[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}

        elif typ == 'market':
            _, oid, side, qty = order
            seq = seq_counter
            seq_counter += 1
            if side == 'buy':
                remaining = match_against(sell_heap, True, None, qty, oid)
            else:
                remaining = match_against(buy_heap, False, None, qty, oid)
            order_info[oid] = {'side': side, 'price': None, 'qty': 0, 'seq': seq, 'active': False}

    return trades

